#include <stdio.h>

typedef unsigned long Roll;
typedef struct Mark { Roll roll; int score; } Mark;

int main(void)
{
    Mark student = {17UL, 82};
    printf("%lu %d\n", student.roll, student.score);
    return 0;
}

#include <stdio.h>

typedef int *IntPointer;

int main(void)
{
    int value = 10;
    IntPointer first = &value, second = &value;
    *second = 25;
    printf("%d %d\n", *first, *second);
    return 0;
}

#include <stdio.h>

typedef int *IntPointer;

int main(void)
{
    int value = 4;
    IntPointer const fixed_pointer = &value;
    *fixed_pointer = 9;
    const int *read_only = &value;
    printf("%d %d\n", value, *read_only);
    return 0;
}

examQuestions.question:
Trace a const pointer alias and a read-only target view.

#include <stdio.h>

typedef int *IntPointer;

int main(void)
{
    int value = 4;
    IntPointer const fixed_pointer = &value;
    *fixed_pointer = 9;
    const int *read_only = &value;
    printf("%d %d\n", value, *read_only);
    return 0;
}
